import { useState } from "react";
import { useWriteContract, useWaitForTransactionReceipt } from "wagmi";
import { parseEther } from "viem";
import { GATEKEEPER_ADDRESS, GATEKEEPER_ABI } from "@/lib/abi/gatekeeper";

export default function SponsorGasForm() {
  const [user, setUser] = useState("");
  const [maxAmount, setMaxAmount] = useState("");

  const {
    data: hash,
    isPending,
    writeContract,
    error,
  } = useWriteContract();

  const { isLoading: isConfirming, isSuccess } =
    useWaitForTransactionReceipt({
      hash,
    });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!user || !maxAmount) return;

    writeContract({
      address: GATEKEEPER_ADDRESS,
      abi: GATEKEEPER_ABI,
      functionName: "sponsorGas",
      args: [user, parseEther(maxAmount)],
      value: parseEther(maxAmount),
    });
  };

  return (
    <div className="max-w-md mx-auto bg-gray-900 p-6 rounded-xl shadow-lg border border-gray-700">
      <h2 className="text-xl font-semibold mb-4 text-white">Sponsor Gas</h2>

      <form onSubmit={handleSubmit} className="space-y-4">
        <div>
          <label className="block text-gray-300 mb-1">User Address</label>
          <input
            type="text"
            value={user}
            onChange={(e) => setUser(e.target.value)}
            className="w-full px-3 py-2 rounded bg-gray-800 text-white border border-gray-700 focus:outline-none focus:ring focus:ring-blue-500"
            placeholder="0x123..."
          />
        </div>

        <div>
          <label className="block text-gray-300 mb-1">Max Amount (ETH)</label>
          <input
            type="text"
            value={maxAmount}
            onChange={(e) => setMaxAmount(e.target.value)}
            className="w-full px-3 py-2 rounded bg-gray-800 text-white border border-gray-700 focus:outline-none focus:ring focus:ring-blue-500"
            placeholder="0.01"
          />
        </div>

        <button
          type="submit"
          disabled={isPending}
          className="w-full py-2 bg-blue-600 hover:bg-blue-700 disabled:bg-gray-600 rounded text-white font-medium"
        >
          {isPending ? "Sending..." : "Sponsor Gas"}
        </button>
      </form>

      {hash && (
        <p className="text-blue-400 mt-3 break-all">
          Transaction sent: {hash}
        </p>
      )}

      {isConfirming && (
        <p className="text-yellow-400 mt-3">Waiting for confirmation...</p>
      )}

      {isSuccess && (
        <p className="text-green-400 mt-3">Gas sponsored successfully!</p>
      )}

      {error && (
        <p className="text-red-400 mt-3">
          Error: {error.message || "Transaction failed"}
        </p>
      )}
    </div>
  );
}
